invocation.command:
set -eu
command -v remem >/dev/null 2>&1 || { printf '%s\n' "[remem] image does not contain remem 0.6.47. Build memorybench-codex-remem:0.144.1-r5-0.6.47-r7 with `bash scripts/build-codex-remem-docker-image.sh`, then use that image." >&2; exit 1; }
remem --version | grep -F -- "0.6.47" >/dev/null || { printf '%s\n' "[remem] image does not contain remem 0.6.47. Build memorybench-codex-remem:0.144.1-r5-0.6.47-r7 with `bash scripts/build-codex-remem-docker-image.sh`, then use that image." >&2; exit 1; }

set -eu
test -n "${CODEX_BASE_URL:-}" || { printf '%s\n' '[remem] CODEX_BASE_URL is required' >&2; exit 1; }
test -x /usr/local/bin/codex || { printf '%s\n' '[remem] /usr/local/bin/codex is missing' >&2; exit 1; }
install -d -m 0755 "$HOME/.local/bin"
cat >"$HOME/.local/bin/remem-codex" <<'EOF'
#!/bin/sh
: "${CODEX_BASE_URL:?CODEX_BASE_URL is required for Remem memory extraction}"
exec /usr/local/bin/codex -c "openai_base_url=\"${CODEX_BASE_URL}\"" "$@"
EOF
chmod 0755 "$HOME/.local/bin/remem-codex"

